<?php
require dirname(__DIR__,2).'/app/admin.php';require_admin();
$id=(int)($_GET['id']??0);$c=array_fill_keys(['slug','title','full_title','description','line','track','technology','schedule','price_period','materials','requirements','syllabus','start_date','location','status'],'');$c+=['age_min'=>null,'age_max'=>null,'weekly_hours'=>null,'price'=>null,'duration_months'=>3,'image'=>'robot-hero.webp','featured'=>0,'sort_order'=>0];$c['status']='draft';$errors=[];
if($id){$q=db()->prepare('SELECT * FROM courses WHERE id=?');$q->execute([$id]);$c=$q->fetch();if(!$c){http_response_code(404);exit('Programa no encontrado.');}}
if($_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf();[$data,$errors]=validate_course($_POST);$c=$data;
 if(!$errors){
  try{
   if($id){$fields=array_map(fn($key)=>$key.'=?',array_keys($data));$q=db()->prepare('UPDATE courses SET '.implode(',',$fields).' WHERE id=?');$q->execute([...array_values($data),$id]);}
   else{$fields=array_keys($data);$q=db()->prepare('INSERT INTO courses ('.implode(',',$fields).') VALUES ('.implode(',',array_fill(0,count($fields),'?')).')');$q->execute(array_values($data));}
   redirect('admin/index.php?updated=1');
  }catch(PDOException $ex){if(in_array((string)$ex->getCode(),['23000','23505'],true))$errors[]='Ya existe un programa con esa dirección. Usa otro slug.';else throw $ex;}
 }
}
$images=array_values(array_filter(scandir(ROOT.'/public/assets/images'),fn($n)=>preg_match('/^[a-zA-Z0-9_-]+\.(webp|png|jpe?g)$/',$n)));
admin_header($id?'Editar programa':'Nuevo programa'); ?>
<a class="text-link" href="<?=url('admin/index.php')?>">← Volver al catálogo</a><?php if($errors):?><div class="form-error" role="alert"><ul><?php foreach($errors as $error):?><li><?=e($error)?></li><?php endforeach;?></ul></div><?php endif;?><form class="course-form" method="post"><?=csrf_field()?>
<section><h2>Información principal</h2><div class="form-grid"><div><label for="title">Nombre corto *</label><input id="title" name="title" required maxlength="200" value="<?=e($c['title'])?>"></div><div><label for="slug">Dirección del programa (slug) *</label><input id="slug" name="slug" required pattern="[a-z0-9]+(-[a-z0-9]+)*" maxlength="190" placeholder="robotica-lego" value="<?=e($c['slug'])?>"></div><div class="span-two"><label for="full_title">Nombre completo</label><input id="full_title" name="full_title" maxlength="1000" value="<?=e($c['full_title'])?>"></div><div class="span-two"><label for="description">Descripción *</label><textarea id="description" name="description" rows="4" required><?=e($c['description'])?></textarea></div><div><label for="line">Línea *</label><select name="line" id="line" required><option value="">Seleccionar</option><?php foreach(lines() as $key=>$label):?><option value="<?=$key?>" <?=$c['line']===$key?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div><label for="track">Nivel EDGE</label><select name="track" id="track"><option value="">No aplica</option><?php foreach(tracks() as $key=>$label):?><option value="<?=$key?>" <?=$c['track']===$key?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div><label for="age_min">Edad mínima</label><input id="age_min" name="age_min" type="number" min="3" max="99" value="<?=e($c['age_min'])?>"></div><div><label for="age_max">Edad máxima (vacío = sin máximo)</label><input id="age_max" name="age_max" type="number" min="3" max="99" value="<?=e($c['age_max'])?>"></div><div><label for="technology">Tecnología *</label><input id="technology" name="technology" required maxlength="60" value="<?=e($c['technology'])?>"></div><div><label for="image">Imagen</label><select name="image" id="image"><?php foreach($images as $img):?><option value="<?=e($img)?>" <?=$c['image']===$img?'selected':''?>><?=e($img)?></option><?php endforeach;?></select><small>Para añadir otra, coloca su archivo en public/assets/images.</small></div></div></section>
<section><h2>Fechas e inversión</h2><p>Deja los campos desconocidos vacíos. La web mostrará “Consultar”.</p><div class="form-grid"><?php foreach([['duration_months','Duración en meses *','number','min="1" max="60" required'],['weekly_hours','Horas por semana','number','min="0" max="168" step="0.5"'],['schedule','Días y horario','text','maxlength="255"'],['start_date','Próximo inicio','date',''],['location','Sede','text','maxlength="255"'],['price','Precio USD','number','min="0" max="999999" step="0.01"'],['price_period','Concepto del precio (total / mensual / módulo)','text','maxlength="100"']] as [$field,$label,$type,$attrs]):?><div><label for="<?=$field?>"><?=$label?></label><input id="<?=$field?>" name="<?=$field?>" type="<?=$type?>" <?=$attrs?> value="<?=e($c[$field])?>"></div><?php endforeach;?></div></section>
<section><h2>Contenido y requisitos</h2><div class="form-grid"><?php foreach(['syllabus'=>'Temario (un punto por línea)','requirements'=>'Conocimientos previos y requisitos','materials'=>'Materiales incluidos y necesarios'] as $field=>$label):?><div class="span-two"><label for="<?=$field?>"><?=$label?></label><textarea id="<?=$field?>" name="<?=$field?>" rows="4"><?=e($c[$field])?></textarea></div><?php endforeach;?></div></section><section><h2>Publicación</h2><div class="form-grid"><div><label for="status">Estado</label><select id="status" name="status"><?php foreach(['draft'=>'Borrador','published'=>'Publicado','archived'=>'Archivado'] as $key=>$label):?><option value="<?=$key?>" <?=$c['status']===$key?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div><label for="sort_order">Orden (menor aparece primero)</label><input id="sort_order" type="number" name="sort_order" min="0" max="99999" value="<?=e($c['sort_order'])?>"></div><div class="span-two"><label class="checkbox-label"><input type="checkbox" name="featured" value="1" <?=$c['featured']?'checked':''?>> Destacar en la página de inicio</label></div></div></section><div class="form-actions"><button class="button" type="submit">Guardar programa <?=icon('check')?></button><a href="<?=url('admin/index.php')?>">Cancelar</a></div></form><?php admin_footer(); ?>
